{
  "name": "Calpine daily gas nomination intake",
  "change": "Replace Calpine's emailed Word-document nomination, phone call and confirm reply with a structured feed that loads into scheduling and acknowledges itself automatically.",
  "reason": "The savings rest on steps the mail does not show: phone calls appear in only 5 of 22 Calpine nominations and Calpine says it calls only for changes, no HPL scheduler confirmation reply exists (the one cited is an undated internal note by Darron Giron, who is not the scheduler), and weekend nominations come in one Friday email, so 30 per month at 14 minutes each is overstated.",
  "research": "Find HPL scheduler replies or confirmations to Calpine (from Lloyd, Lannou or Kemp) and any mail showing how long keying the .doc takes or how many other shippers send Word nominations; without that, the only supported saving is a few minutes of re-keying per weekday from a single counterparty."
}

{
  "name": "Monthly OPM hours and activity driver surveys",
  "change": "Pull activity driver counts from Sitara/Unify reports and make the hours survey exception-only, carrying last month's hours forward",
  "reason": "The proposal costs the spreadsheet-and-email process from mid-2000, which the OPM team had already replaced: from September 2000 the hours survey is an Access database that rolls prior-month data forward and shows prior-month hours, driver automation was already under way, and no activity driver survey appears after August 2000, so most of the claimed 778 minutes a month is no longer spent.",
  "research": "Find mail from after September 2000 showing managers still hand-filling activity driver counts, or still re-entering unchanged hours in the Access survey, and size only that remaining work against the database process as it then ran."
}

{
  "name": "Rebooking deals to the right legal entity from the daily Credit Report",
  "change": "Add a credit-maintained alias table in TAGG that books known wrong entities to the approved one, and route each day's remaining exceptions by book instead of a desk lead forwarding the whole report",
  "reason": "The mail contradicts the fixed wrong-to-right pairs the alias table depends on (the same entity is sent to different targets, and Aquila/Utilicorp are rebooked in both directions), and the 9 minutes a day of West-desk rebooks, which make up half the savings, are not supported by anything in the mail.",
  "research": "Find mail that shows which Credit Report lines belong to the West desk's books and how long a rebook takes, and check across all the reports whether each wrong entity always goes to the same target (only about 10 of the ~70 forwarded reports have the list in the message body)."
}

{
  "name": "Monthly P&L top pages for Arthur Andersen gas testing",
  "today": "Each month Arthur Andersen (AA) picks gas regions from the monthly P&L statement and emails the gas risk desk leads (Kelly, Keiser, Giron, Baumbach and others) asking for each region's P&L top page for the last day of the month, plus top pages and Curve Shift Reports for the five largest days when curve shift drives the P&L. Each lead forwards the request to analysts, who find, copy and send the pages. AA also has to ask which person owns each desk, chases missing pages, and waits when the lead is away.",
  "change": "Save each gas book's month-end and daily P&L top pages and curve shift reports automatically to a read-only audit folder, with a list of who owns each book, so AA can pull the pages itself.",
  "explanation": "The P&L top pages and Curve Shift Reports are already produced every day. A scheduled job would copy each book's daily top page and curve shift report into a read-only folder sorted by month and book, and the risk group would keep a one-page list of who owns each book next to it. AA would get read access. Each month AA would choose its regions and take the month-end and largest-day pages from the folder without emailing the desk leads. The analysts would only take part in the follow-up talk about what drove each region's P&L, which stays the same. One thing to settle first: AA said its staff would lose access to Enron Lotus Notes from 28 February 2001, so the folder would need to be reachable without that access.",
  "occurrences": [
    {
      "file": "corpus/giron-d/sent/516.eml",
      "quote": "In order for us to complete our monthly gas testing, please provide the \nfollowing items."
    },
    {
      "file": "corpus/giron-d/sent/515.eml",
      "quote": "Please provide us with the P&L top sheet as of October 31 for the following \nbooks."
    },
    {
      "file": "corpus/giron-d/sent/326.eml",
      "quote": "We are requesting that you supply the P & L top pages for the \nlast day of the month for those regions that are applicable to you."
    },
    {
      "file": "corpus/giron-d/sent/201.eml",
      "quote": "Please make sure this guy gets what he needs."
    }
  ],
  "evidence": [
    {
      "file": "corpus/giron-d/sent/516.eml",
      "quote": "Additionally, if the majority of \nthe P&L pertains to curve shift, please provide the P&L top pages for five \nof  the  largest days including the Curve Shift Reports.",
      "note": "Besides the month-end page, each region may need five more daily top pages and curve shift reports. Eight region-months were asked for in this one request."
    },
    {
      "file": "corpus/giron-d/sent/516.eml",
      "quote": "Please get this info to me and I will pass it on to AA.",
      "note": "The desk lead routes the request to four analysts, then collects their pages and sends them on."
    },
    {
      "file": "corpus/giron-d/sent/420.eml",
      "quote": "Pull this together and then call Sharon so they can come get the copies.",
      "note": "The pages are pulled and copied by hand. Pages for some third-quarter regions were still missing a month later, so AA had to chase them."
    },
    {
      "file": "corpus/giron-d/sent/299.eml",
      "quote": "please direct me to the individual responsible \nfor each of the desks listed below.",
      "note": "AA cannot tell who owns each book, so the lead must answer that too. A list of book owners in the folder removes this step."
    },
    {
      "file": "corpus/giron-d/sent/201.eml",
      "quote": "To: William Kelly/HOU/ECT@ECT, Kam Keiser/HOU/ECT@ECT, Darron C \nGiron/HOU/ECT@ECT, David Baumbach/HOU/ECT@ECT",
      "note": "The same request reaches several desk leads, and each one reads and routes it."
    }
  ],
  "stalls": [
    {
      "file": "corpus/giron-d/sent/326.eml",
      "quote": "Is there someone else that can direct us to?  I would like to get this \ninformation as soon as it is possible.",
      "note": "AA's testing waited because the desk lead was travelling and nobody else was named as the source of the pages."
    }
  ],
  "ongoing": true,
  "stated_rate": {
    "count": 1,
    "per": "month",
    "file": "corpus/giron-d/sent/326.eml",
    "quote": "As part of our monthly testing we review the monthly Natural Gas P & L \nStatement"
  },
  "minutes": 95
}

