{
  "name": "Waiting on Path Confirmation saves during nightly checkouts",
  "today": "Each night between HE 19 and HE 21 the Portland Real Time shift trader calls the major marketers and utilities (27 are named) to check out the day's schedules, and records each confirmation in the Enpower Path Confirmation application. The trader sorts paths by counterparty, highlights that counterparty's paths (several rows can be selected at once), clicks the telephone icon and types the counterparty's contact details. That entry saves directly to the Enpower database and takes about a minute, during which the trader waits before moving on. Cut paths are also recorded in the same application as confirms with comments, so they hit the same save.",
  "change": "Make Path Confirmation save confirmations in the background so the shift trader does not wait about a minute after each one.",
  "explanation": "The Enpower team would change the Path Confirmation confirm screen so it closes as soon as the trader enters the contact details, and the write to Enpower finishes in the background (with a flag on the row if the save fails). The Real Time shift traders would use it as today: sort by counterparty, highlight the paths, click the telephone icon, enter the contact. The calls and data entry stay the same; only the wait of about a minute per save goes away, which matters because the checkouts must fit into a two-hour window on a desk that is also trading in real time.",
  "occurrences": [
    {
      "file": "corpus/williams-w3/sent_items/86.eml",
      "quote": "You must check out with all major marketers and utilities each night."
    },
    {
      "file": "corpus/williams-w3/sent_items/62.eml",
      "quote": "In the Enpower Path Confirmation, we need to make cuts as Path Confirms. Enter comments in the confirmed section."
    }
  ],
  "evidence": [
    {
      "file": "corpus/williams-w3/sent_items/86.eml",
      "quote": "Confirm a path by highlighting and clicking the telephone icon. A screen will come up requesting contact information from the appropriate counterparty. Because this information saves directly to Enpower, save time runs about a minute.",
      "note": "Each confirmation save makes the trader wait about a minute; a background save removes that wait."
    },
    {
      "file": "corpus/williams-w3/sent_items/86.eml",
      "quote": "AEP, AES-New Energy, Aquila, Avista, Calpine, Constellation, Coral, Duke, Dynegy, El Paso Merchant, Exelon, Meico, Mirant, Morgan, NCPA, Reliant, PPLMontana, PowerX, Sempra, SMUD, TransAlta, Williams, and southwest utilities such as Pinnacle West, SRP, PNM, PSCO and Pacificorp",
      "note": "27 counterparties are named for nightly checkout. Paths can already be highlighted together, so about one save per counterparty is assumed; with perhaps 15 active on a typical night (many were cutting back on trading with Enron at the time), that is about 15 saves."
    },
    {
      "file": "corpus/williams-w3/sent_items/86.eml",
      "quote": "These checkouts should be started in HE 19 and finished by HE 21.",
      "note": "The checkouts must fit into a two-hour window, so the waiting comes out of time that is already tight."
    }
  ],
  "stalls": [],
  "ongoing": true,
  "stated_rate": {
    "count": 1,
    "per": "day",
    "file": "corpus/williams-w3/sent_items/86.eml",
    "quote": "You must check out with all major marketers and utilities each night."
  },
  "minutes": 13
}

